bool GlAccounts::validJsonOfField(size_t index,
                                  const std::string &fieldName,
                                  const Json::Value &pJson,
                                  std::string &err,
                                  bool isForCreation)
{
    switch(index)
    {

        case 0:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 1:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 2:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 3:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 4:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 5:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            if(pJson.isString() && drogon::utils::utf8Length(pJson.asCString()) > 80)
            {
                err="String length exceeds limit for the " +
                    fieldName +
                    " field (the maximum value is 80)";
                return false;
            }

            break;

        case 6:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            if(pJson.isString() && drogon::utils::utf8Length(pJson.asCString()) > 200)
            {
                err="String length exceeds limit for the " +
                    fieldName +
                    " field (the maximum value is 200)";
                return false;
            }

            break;

        case 7:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            if(pJson.isString() && drogon::utils::utf8Length(pJson.asCString()) > 20)
            {
                err="String length exceeds limit for the " +
                    fieldName +
                    " field (the maximum value is 20)";
                return false;
            }

            break;

        case 8:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 9:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isInt())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 10:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isBool())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 11:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isBool())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 12:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 13:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 14:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 15:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 16:

            if(pJson.isNull())
            {
                err="The " + fieldName + " column cannot be null";
                return false;
            }

            if(!pJson.isBool())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 17:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        case 18:

            if(pJson.isNull())
            {
                return true;
            }

            if(!pJson.isString())
            {
                err="Type error in the "+fieldName+" field";
                return false;
            }

            break;

        default:
            err="Internal error in the server";
            return false;
    }
    return true;
}

CoreCurrencies GlAccounts::getCoreCurrencies(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from core_currencies where id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *currencyId_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    if (r.size() == 0)
    {
        throw UnexpectedRows("0 rows found");
    }
    else if (r.size() > 1)
    {
        throw UnexpectedRows("Found more than one row");
    }
    return CoreCurrencies(r[0]);
}

void GlAccounts::getCoreCurrencies(const DbClientPtr &clientPtr,
                                   const std::function<void(CoreCurrencies)> &rcb,
                                   const ExceptionCallback &ecb) const
{
    static const std::string sql = "select * from core_currencies where id = $1";
    *clientPtr << sql
               << *currencyId_
               >> [rcb = std::move(rcb), ecb](const Result &r){
                    if (r.size() == 0)
                    {
                        ecb(UnexpectedRows("0 rows found"));
                    }
                    else if (r.size() > 1)
                    {
                        ecb(UnexpectedRows("Found more than one row"));
                    }
                    else
                    {
                        rcb(CoreCurrencies(r[0]));
                    }
               }
               >> ecb;
}

